    def test_queued(self):
        task = {'state': 'queued'}
        self.assertEqual(next_recovery(task), 'retry')

    def test_failed_retryable(self):
        task = {'state': 'failed', 'attempts': 1, 'max_attempts': 3}
        self.assertEqual(next_recovery(task), 'retry')

    def test_failed_escalate(self):
        task = {'state': 'failed', 'attempts': 3, 'max_attempts': 3}
        self.assertEqual(next_recovery(task), 'escalate')

