    def test_unknown_state(self):
        task = {'state': 'unknown'}
        with self.assertRaisesRegex(ValueError, "Unknown state: unknown"):
            next_recovery(task)

    def test_no_mutation(self):
        task = {'state': 'queued', 'attempts': 1}
        original_task = task.copy()
        next_recovery(task)
        self.assertEqual(task, original_task)

if __name__ == '__main__':
